// Périmètre : dossiers ouverts, ou modifiés/clôturés depuis moins de 90 jours.
// Seuls les dossiers nouveaux ou modifiés depuis la dernière synchronisation sont relus en détail (quota noCRM : 2 000 requêtes/jour).
const J90 = 90 * 24 * 3600 * 1000;
const maintenant = Date.now();

const aplatir = (items) => items.flatMap(it => Array.isArray(it.json) ? it.json : [it.json]);

const commerciaux = {};
for (const u of aplatir($('noCRM – utilisateurs').all())) {
  if (u && u.id) commerciaux[u.id] = [u.firstname, u.lastname].filter(Boolean).join(' ');
}

const connus = {};
for (const it of $('Airtable – opportunités existantes').all()) {
  const f = it.json.fields || it.json;
  if (f && f.nocrm_id) connus[f.nocrm_id] = f['Modifié le'] ? Date.parse(f['Modifié le']) : 0;
}

const leads = aplatir($('noCRM – opportunités').all()).filter(l => l && l.id);
const sortie = [];
for (const l of leads) {
  const ouvert = l.status === 'todo' || l.status === 'standby';
  const reference = Date.parse(l.closed_at || l.updated_at || l.created_at);
  if (!ouvert && maintenant - reference > J90) continue;
  const modifie = Date.parse(l.updated_at);
  const dejaAJour = l.id in connus && Math.abs(connus[l.id] - modifie) < 1000;
  if (dejaAJour) continue;
  sortie.push({ json: { id: l.id, commercial: commerciaux[l.user_id] || '', nouveau: !(l.id in connus) } });
}
return sortie;

// Transforme chaque dossier noCRM en ligne Airtable. N'écrit QUE les champs « sync » :
// jamais Relance désactivée, Motif, Devis envoyé le ni Réponse client reçue le.
const STATUT = { todo: 'En cours', standby: 'En attente', won: 'Gagné', lost: 'Perdu', cancelled: 'Annulé' };
const commerciaux = {};
for (const s of $('Sélection des dossiers à mettre à jour').all()) commerciaux[s.json.id] = s.json.commercial;

const nombre = (s) => {
  if (s == null) return null;
  const n = parseFloat(String(s).replace(/[\s\u00a0\u202f]/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};
const RUE = /^(n°?\s*)?\d|\b(rue|avenue|av\.?|all[ée]e|chemin|bd|boulevard|impasse|place|cours|route|quai|lotissement|r[ée]sidence|lieu[- ]dit|passage|square|voie|parvis|esplanade)\b/i;
// Ville lue dans une adresse libre ; vide si illisible, jamais devinée.
const villeDe = (brut) => {
  let v = (brut || '').replace(/[\u{1F300}-\u{1FAFF}\u2600-\u27BF\uFE0F]/gu, '').replace(/\s+[—–-]\s+.*$/, '').trim();
  if (!v) return '';
  const fin = (s) => s.split(/\s{2,}/)[0].trim();
  let m = v.match(/\b\d{5}\s+([A-Za-zÀ-ÿ][^,\n(]*?)\s*(?:[,(]|$)/);
  if (m) return fin(m[1]);
  m = v.match(/([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ'’\- ]*?)\s*\(\s*\d{5}\s*\)/);
  if (m) return fin(m[1]);
  m = v.match(/([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ'’\- ]*?)\s+\d{5}\b/);
  if (m && !RUE.test(m[1])) return fin(m[1]);
  v = v.replace(/\([^)]*\)/g, '').trim();
  const segs = v.split(',').map(s => s.trim()).filter(Boolean);
  if (!segs.length) return '';
  // Nom de ville sans code postal : doit commencer par une majuscule (écarte « pas de logement », « à définir »…).
  const propre = (s) => !/\d/.test(s) && !RUE.test(s) && s.length <= 40 && /^[A-ZÀ-Ý]/.test(s);
  if (segs.length === 1) return propre(segs[0]) ? fin(segs[0]) : '';
  if (propre(segs[0])) return fin(segs[0]);
  const dernier = segs[segs.length - 1];
  return propre(dernier) ? fin(dernier) : '';
};
// Cherche « Départ : … » ; à défaut, la ligne qui suit « Ville de départ ».
const ville = (texte, sens) => {
  const lignes = texte.split(/\r?\n/).map(l => l.trim());
  const deuxPoints = sens === 'depart' ? /^d[ée]part\s*:\s*(.+)$/i : /^arriv[ée]e\s*:\s*(.+)$/i;
  const titre = sens === 'depart' ? /^ville\s+de\s+d[ée]part\s*:?$/i : /^ville\s+d.\s*arriv[ée]e\s*:?$/i;
  for (const l of lignes) {
    const m = l.match(deuxPoints);
    if (m) { const v = villeDe(m[1]); if (v) return v; break; }
  }
  const i = lignes.findIndex(l => titre.test(l));
  if (i >= 0) {
    const suivante = lignes.slice(i + 1).find(l => l.replace(/\u00a0/g, '').trim());
    if (suivante) return villeDe(suivante);
  }
  return '';
};
const date = (d) => (d ? new Date(d).toISOString() : null);

const lignes = [];
for (const it of $input.all()) {
  const l = it.json;
  if (!l || !l.id) continue;
  const ei = l.extended_info || {};
  const f = ei.fields || {};
  const desc = l.description || '';
  const vol = desc.match(/Volume de meuble\s*:\s*([\d.,]+)\s*m/i);
  const prix = [...desc.matchAll(/Prix Total\s*:\s*([\d\s\u00a0\u202f.,]+)€\s*TTC/gi)].map(m => nombre(m[1])).filter(n => n != null);
  const email = (f.email || ei.first_contact_email || '').trim();
  lignes.push({
    'Titre': l.title || '',
    'nocrm_id': l.id,
    'Prénom': f.first_name || '',
    'Nom': f.last_name || '',
    'E-mail': email || null,
    'Téléphone': f.phone || f.mobile || '',
    'Étape': l.step || null,
    'Statut': STATUT[l.status] || null,
    'Montant TTC': l.amount != null ? Number(l.amount) : null,
    'Commercial': commerciaux[l.id] || [ (ei.user || {}).firstname, (ei.user || {}).lastname ].filter(Boolean).join(' '),
    'Départ': ville(desc, 'depart'),
    'Arrivée': ville(desc, 'arrivee'),
    'Volume (m³)': vol ? nombre(vol[1]) : null,
    'Prix TTC extrait': prix.length ? Math.max(...prix) : null,
    'Prochaine action': date(l.next_action_at),
    'Créé le': date(l.created_at),
    'Modifié le': date(l.updated_at),
    'Clôturé le': date(l.closed_at),
    'Lien noCRM': ei.permalink || ('https://samdemenage.nocrm.io/leads/' + l.id),
    'Dernière sync': new Date().toISOString()
  });
}

// Lots de 10 : limite de l'API Airtable par requête.
const lots = [];
for (let i = 0; i < lignes.length; i += 10) {
  lots.push({ json: { records: lignes.slice(i, i + 10).map(fields => ({ fields })) } });
}
return lots;

// Met en forme l'alerte et calcule une clé de regroupement (nœud + message + heure).
const d = $json.execution || {};
const w = $json.workflow || {};
const noeud = d.lastNodeExecuted || 'inconnu';
const message = (d.error && (d.error.message || d.error.description)) || 'erreur sans message';
const quand = new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' });
const heure = new Date().toISOString().slice(0, 13);
const texte = [
  ':rotating_light: *Relances devis — échec d’exécution*',
  '*Bloc / workflow :* ' + (w.name || 'inconnu'),
  '*Nœud en échec :* ' + noeud,
  '*Message :* ' + String(message).slice(0, 800),
  '*Quand :* ' + quand,
  d.url ? '*Exécution :* ' + d.url : '*Exécution :* ' + (d.id || '—')
].join(String.fromCharCode(10));
return [{ json: { texte, cle: noeud + '|' + String(message).slice(0, 120) + '|' + heure } }];

